"""Tests for refactor_move_rewrite."""

from __future__ import annotations

import os

from lintgate.refactor_move_rewrite import (
    _compute_rewrites,
    _extract_public_names,
    _rewrite_import_aliases,
    generate_shim,
    smoke_test_import,
)


def test_compute_rewrites_fills_new_text():
    from lintgate.refactor_move import ImportReference

    refs = [
        ImportReference(
            file="a.py", line=1, kind="from_import", old_text="lintgate.old", new_text=""
        ),
        ImportReference(
            file="b.py", line=2, kind="string_ref", old_text="lintgate.old.sub", new_text=""
        ),
    ]
    _compute_rewrites(refs, "lintgate.old", "lintgate.new")
    assert refs[0].new_text == "lintgate.new"
    assert refs[1].new_text == "lintgate.new.sub"


def test_compute_rewrites_skips_non_matching_kinds():
    from lintgate.refactor_move import ImportReference

    ref = ImportReference(file="a.py", line=1, kind="other", old_text="lintgate.old", new_text="")
    _compute_rewrites([ref], "lintgate.old", "lintgate.new")
    assert ref.new_text == ""


def test_rewrite_import_aliases_changes_matching():
    try:
        import libcst as cst
    except ImportError:
        import pytest

        pytest.skip("libcst not installed")

    aliases = [
        cst.ImportAlias(name=cst.Attribute(value=cst.Name("lintgate"), attr=cst.Name("old")))
    ]
    new_aliases, changed = _rewrite_import_aliases(aliases, "lintgate.old", "lintgate.new")
    assert changed is True
    assert len(new_aliases) == 1


