def test_generate_shim_creates_file(tmp_path):
    src = tmp_path / "lintgate" / "new_mod.py"
    src.parent.mkdir(parents=True)
    src.write_text("def foo(): pass\ndef bar(): pass\n")

    result = generate_shim(str(tmp_path), "lintgate.old_mod", "lintgate.new_mod")
    assert os.path.isfile(result)
    content = open(result).read()
    assert "from lintgate.new_mod import *" in content


def test_extract_public_names_from_all(tmp_path):
    src = tmp_path / "mod.py"
    src.write_text('__all__ = ["foo", "bar"]\ndef foo(): pass\ndef _private(): pass\n')
    names = _extract_public_names(str(src))
    assert names == ["foo", "bar"]


def test_extract_public_names_fallback(tmp_path):
    src = tmp_path / "mod.py"
    src.write_text("def foo(): pass\ndef _private(): pass\nclass Bar: pass\n")
    names = _extract_public_names(str(src))
    assert "foo" in names
    assert "Bar" in names
    assert "_private" not in names


def test_smoke_test_import_success():
    ok, err = smoke_test_import("os", os.getcwd())
    assert ok is True
    assert err == ""


def test_smoke_test_import_failure():
    ok, err = smoke_test_import("nonexistent_module_xyz_12345", os.getcwd())
    assert ok is False
    assert err != ""
